HC_BeatenText_A2_10:
	text "The elders will"
	line "hear about this."
	para "They won't care."
	line "They're asleep."
	done

HC_BeatenText_A2_11:
	text "I lost? I lost!"
	line "Wow. That doesn't"
	para "feel like sharing"
