HC_AfterText_A2_0:
	text "We don't have a"
	line "word for what"
	para "you're doing. We"
	line "made one up. It's"
	para "'rude'."
	done

HC_AfterText_A2_1:
	text "Someone left a"
	line "body in the"
	para "lettuce. Nobody's"
	line "saying who."
	para "Probably the"
	line "lettuce."
	done

HC_AfterText_A2_2:
	text "No locks. No"
	line "walls. No"
	para "judgment. I'm"
	line "starting to see a"
	para "pattern, though."
	done

HC_AfterText_A2_3:
	text "We found a body by"
	line "the river. We're"
	para "still deciding"
	line "whether it's art."
	done

HC_AfterText_A2_4:
	text "My partner went to"
	line "look for the"
	para "others. That was"
	line "an hour ago. I'm"
	para "worried and"
	line "slightly aroused."
	para "That's just how I"
	line "get."
	done

HC_AfterText_A2_5:
	text "Everything's fine."
	line "The forest has"
	para "seen worse. The"
	line "forest is lying."
	done

HC_AfterText_A2_6:
	text "If you see a man"
	line "with a fence, kill"
	para "him. No wait."
	line "Don't. We don't do"
	para "that."
	done

HC_AfterText_A2_7:
	text "The elders say"
	line "balance is key."
